begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate in ('42601','42702','42703','42883','42P01') then raise;end if;raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
insert into branches(id,code,name) values('ef710000-0000-0000-0000-000000000001','COUNT-A','Synthetic count A'),('ef710000-0000-0000-0000-000000000002','COUNT-B','Synthetic count B');
insert into auth.users(id,email) values('ef720000-0000-0000-0000-000000000001','count@example.invalid');
insert into profiles(id,full_name,branch_id,active) values('ef720000-0000-0000-0000-000000000001','Synthetic counter','ef710000-0000-0000-0000-000000000001',true);
insert into roles(id,code,name) values('ef730000-0000-0000-0000-000000000001','COUNT_TEST','Synthetic counts');
insert into role_permissions(role_id,permission_code) values('ef730000-0000-0000-0000-000000000001','BLOOD_INVENTORY_VIEW'),('ef730000-0000-0000-0000-000000000001','BLOOD_INVENTORY_WRITE');
insert into user_roles(user_id,role_id,branch_id) values('ef720000-0000-0000-0000-000000000001','ef730000-0000-0000-0000-000000000001','ef710000-0000-0000-0000-000000000001');
grant execute on all functions in schema pg_temp to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','ef720000-0000-0000-0000-000000000001',true);
select record_operational_blood_counts('ef710000-0000-0000-0000-000000000001','ef740000-0000-0000-0000-000000000001','2026-11-01','[{"component_name":"PLAQUETAS","group_code":"O|POSITIVO","available_units":25,"quarantine_units":3,"reserved_units":2}]');
select pg_temp.ok((select available_units=25 and quarantine_units=3 and reserved_units=2 and revision=1 from vw_operational_blood_inventory where component_name='PLAQUETAS'),'counts store quantities without unit identities');
select id as prior from vw_operational_blood_inventory where component_name='PLAQUETAS' \gset
select pg_temp.ok((record_operational_blood_counts('ef710000-0000-0000-0000-000000000001','ef740000-0000-0000-0000-000000000001','2026-11-01','[{"component_name":"PLAQUETAS","group_code":"O|POSITIVO","available_units":25,"quarantine_units":3,"reserved_units":2}]')->>'already_saved')::boolean,'retry is idempotent');
select record_operational_blood_counts('ef710000-0000-0000-0000-000000000001','ef740000-0000-0000-0000-000000000002','2026-11-02',jsonb_build_array(jsonb_build_object('component_name','PLAQUETAS','group_code','O|POSITIVO','available_units',12,'quarantine_units',0,'reserved_units',1,'previous_id',:'prior')));
select pg_temp.ok((select count(*)=1 and sum(available_units)=12 from vw_operational_blood_inventory),'new count replaces previous total rather than adding it');
select pg_temp.ok((select count(*)=2 from operational_blood_counts),'history retains previous count and responsible');
select pg_temp.denied($q$select record_operational_blood_counts('ef710000-0000-0000-0000-000000000001',gen_random_uuid(),'2026-11-03','[{"component_name":"PLAQUETAS","group_code":"O|POSITIVO","available_units":99,"quarantine_units":0,"reserved_units":0}]')$q$,'stale count cannot overwrite newer data');
select pg_temp.denied($q$select record_operational_blood_counts('ef710000-0000-0000-0000-000000000002',gen_random_uuid(),'2026-11-01','[{"component_name":"PLAQUETAS","group_code":"O|POSITIVO","available_units":1,"quarantine_units":0,"reserved_units":0}]')$q$,'counts cannot cross branch authorization');
select pg_temp.denied($q$select record_operational_blood_counts('ef710000-0000-0000-0000-000000000001',gen_random_uuid(),'2026-11-01','[{"component_name":"Guantes","group_code":"O|POSITIVO","available_units":1,"quarantine_units":0,"reserved_units":0}]')$q$,'supplies cannot enter blood counts');
select pg_temp.denied($q$select record_operational_blood_counts('ef710000-0000-0000-0000-000000000001',gen_random_uuid(),'2026-11-01','[{"component_name":"SANGRE_TOTAL","group_code":"O|POSITIVO","available_units":-1,"quarantine_units":0,"reserved_units":0}]')$q$,'negative count rejected');
select pg_temp.denied($q$select record_operational_blood_counts('ef710000-0000-0000-0000-000000000001',gen_random_uuid(),'2026-11-01','[{"component_name":"SANGRE_TOTAL","group_code":"O|POSITIVO","available_units":5,"quarantine_units":0,"reserved_units":0},{"component_name":"Guantes","group_code":"O|POSITIVO","available_units":1,"quarantine_units":0,"reserved_units":0}]')$q$,'invalid line rolls back entire capture');
select pg_temp.ok(not exists(select 1 from operational_blood_counts where component_name='SANGRE_TOTAL'),'failed capture has no partial saved counts');
select pg_temp.denied($q$update operational_blood_counts set available_units=99$q$,'history cannot be rewritten');
select pg_temp.denied($q$delete from operational_blood_counts$q$,'history cannot be deleted');
select pg_temp.ok(not exists(select 1 from blood_inventory_units where branch_id='ef710000-0000-0000-0000-000000000001'),'no fictitious laboratory units are created');
select pg_temp.ok(not has_function_privilege('anon','public.record_operational_blood_counts(uuid,uuid,date,jsonb)','execute'),'anonymous writes denied');
reset role;
select pg_temp.ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.vw_operational_blood_inventory'::regclass),'current count view honors RLS');
rollback;
